create table public.feed_alerts(id uuid primary key default gen_random_uuid(),post_id uuid not null references public.feed_posts(id)on delete cascade,sender_id uuid not null references public.profiles(id)on delete cascade,recipient_id uuid not null references public.profiles(id)on delete cascade,kind text not null check(kind in('reaction','comment')),source_id text not null,created_at timestamptz not null default clock_timestamp(),claimed_at timestamptz);
alter table public.feed_alerts enable row level security;revoke all on public.feed_alerts from public,anon,authenticated;grant select,update,delete on public.feed_alerts to service_role;
create function public.feed_notify()returns trigger language plpgsql security definer set search_path=public as $$declare recipient uuid;secret text;event_id uuid;begin
 if tg_table_name='feed_reactions'and tg_op='UPDATE'and to_jsonb(new)->>'emoji'=to_jsonb(old)->>'emoji' then return new;end if;
 recipient:=public.friend_id(new.user_id);if recipient is null or not exists(select from public.feed_posts p where p.id=new.post_id and recipient in(p.owner_id,p.partner_id))then return new;end if;
 if exists(select from public.app_settings where user_id=recipient and notifications->'feed'='false'::jsonb)then return new;end if;
 -- Rate-limit alert noise without blocking the reaction/comment itself.
 if exists(select from public.feed_alerts where sender_id=new.user_id and recipient_id=recipient and post_id=new.post_id and created_at>now()-interval '30 seconds')then return new;end if;
 insert into public.feed_alerts(post_id,sender_id,recipient_id,kind,source_id)values(new.post_id,new.user_id,recipient,case when tg_table_name='feed_reactions'then 'reaction'else 'comment'end,case when tg_table_name='feed_reactions'then new.user_id::text else to_jsonb(new)->>'id' end)returning id into event_id;
 begin select decrypted_secret into secret from vault.decrypted_secrets where name='diary_push_cron'limit 1;if secret is not null then perform net.http_post(url:='https://etkjcywiaiiphsrthxqe.supabase.co/functions/v1/send-feed-push',headers:=jsonb_build_object('Content-Type','application/json','x-diary-cron',secret),body:=jsonb_build_object('id',event_id),timeout_milliseconds:=10000);end if;exception when others then null;end;
 delete from public.feed_alerts where created_at<now()-interval '7 days';return new;end$$;
revoke all on function public.feed_notify()from public,anon,authenticated;
create trigger feed_reaction_notify after insert or update on public.feed_reactions for each row execute function public.feed_notify();create trigger feed_comment_notify after insert on public.feed_comments for each row execute function public.feed_notify();
create function public.claim_feed_alert(p_id uuid)returns setof public.feed_alerts language sql security definer set search_path=public as $$
 update public.feed_alerts e set claimed_at=clock_timestamp()where e.id=p_id and e.claimed_at is null and e.created_at>now()-interval '2 minutes'and public.friend_id(e.sender_id)=e.recipient_id and exists(select from public.feed_posts p where p.id=e.post_id and e.sender_id in(p.owner_id,p.partner_id)and e.recipient_id in(p.owner_id,p.partner_id))and not exists(select from public.app_settings s where s.user_id=e.recipient_id and s.notifications->'feed'='false'::jsonb)and(case when e.kind='reaction'then exists(select from public.feed_reactions r where r.post_id=e.post_id and r.user_id=e.sender_id and r.created_at<=e.created_at)else exists(select from public.feed_comments c where c.id::text=e.source_id and c.post_id=e.post_id)end)returning e.*;$$;
revoke all on function public.claim_feed_alert(uuid)from public,anon,authenticated;grant execute on function public.claim_feed_alert(uuid)to service_role;
